-- Privacy-preserving site-search analytics and content discovery.
create table if not exists public.cms_search_events(id uuid primary key default gen_random_uuid(),query_text text not null check(length(query_text)between 2 and 100),locale text not null check(locale in('en','ar','fr','ru','es','pt')),result_count integer not null check(result_count>=0),searched_at timestamptz not null default now());
create table if not exists public.cms_search_clicks(id uuid primary key default gen_random_uuid(),search_event_id uuid not null references public.cms_search_events(id)on delete cascade,page_key text not null,result_position integer not null check(result_position between 1 and 20),clicked_at timestamptz not null default now(),unique(search_event_id,page_key));
create index if not exists cms_search_events_time_idx on public.cms_search_events(searched_at desc);create index if not exists cms_search_events_query_idx on public.cms_search_events(locale,query_text,searched_at desc);create index if not exists cms_search_clicks_page_idx on public.cms_search_clicks(page_key,clicked_at desc);
alter table public.cms_search_events enable row level security;alter table public.cms_search_clicks enable row level security;revoke all on public.cms_search_events,public.cms_search_clicks from public,anon,authenticated;
create or replace function public.cms_search_discover(p_query text,p_locale text default'en',p_limit integer default 12)returns jsonb language plpgsql security definer set search_path=public as $$declare v_query text:=regexp_replace(trim(p_query),'\s+',' ','g');v_safe text;v_results jsonb;v_count integer;v_event uuid;begin if length(v_query)<2 or length(v_query)>100 then raise exception'search_query_length_invalid';end if;if p_locale not in('en','ar','fr','ru','es','pt')then raise exception'unsupported_locale';end if;select coalesce(jsonb_agg(to_jsonb(r)order by r.rank desc,r.updated_at desc),'[]'),count(*)into v_results,v_count from public.cms_search_site(v_query,p_locale,p_limit)r;v_safe:=lower(v_query);if v_safe~*'[[:alnum:]._%+-]+@[[:alnum:].-]+\.[[:alpha:]]{2,}'or v_safe~'\+?[0-9][0-9 ()-]{6,}[0-9]'then v_safe:='[redacted sensitive query]';end if;insert into public.cms_search_events(query_text,locale,result_count)values(v_safe,p_locale,v_count)returning id into v_event;return jsonb_build_object('search_id',v_event,'results',v_results,'result_count',v_count);end$$;
create or replace function public.cms_record_search_click(p_search_id uuid,p_page_key text,p_position integer)returns void language plpgsql security definer set search_path=public as $$begin if p_position not between 1 and 20 then raise exception'invalid_result_position';end if;if not exists(select 1 from public.cms_search_events where id=p_search_id and searched_at>now()-interval'24 hours')then raise exception'search_event_not_found';end if;if not exists(select 1 from public.cms_pages where page_key=p_page_key and status='published'and published_content is not null)then raise exception'published_page_not_found';end if;insert into public.cms_search_clicks(search_event_id,page_key,result_position)values(p_search_id,p_page_key,p_position)on conflict(search_event_id,page_key)do nothing;end$$;
create or replace function public.cms_search_suggestions(p_prefix text,p_locale text default'en',p_limit integer default 6)returns table(label text,route text)language plpgsql stable security definer set search_path=public as $$declare v_prefix text:=trim(p_prefix);v_limit integer:=least(greatest(coalesce(p_limit,6),1),8);begin if length(v_prefix)<2 or length(v_prefix)>100 then return;end if;if p_locale not in('en','ar','fr','ru','es','pt')then raise exception'unsupported_locale';end if;return query select distinct coalesce(case when p_locale='en'then p.title else p.published_content->'translations'->p_locale->'seo'->>'title'end,p.title),p.route from public.cms_pages p where p.status='published'and p.published_content is not null and(coalesce(case when p_locale='en'then p.title else p.published_content->'translations'->p_locale->'seo'->>'title'end,p.title)ilike'%'||v_prefix||'%'or p.route ilike'%'||replace(v_prefix,' ','-')||'%')order by 1 limit v_limit;end$$;
create or replace function public.cms_popular_content(p_locale text default'en',p_limit integer default 6)returns table(page_key text,title text,route text,page_type text,snippet text,clicks bigint)language plpgsql stable security definer set search_path=public as $$declare v_limit integer:=least(greatest(coalesce(p_limit,6),1),12);begin if p_locale not in('en','ar','fr','ru','es','pt')then raise exception'unsupported_locale';end if;return query select p.page_key,coalesce(case when p_locale='en'then p.title else p.published_content->'translations'->p_locale->'seo'->>'title'end,p.title),p.route,p.page_type,left(regexp_replace(coalesce(p.published_content->'seo'->>'description',p.published_content->>'description',p.published_content::text),'[{}\[\]"]',' ','g'),220),count(c.id)from public.cms_pages p left join public.cms_search_clicks c on c.page_key=p.page_key and c.clicked_at>now()-interval'30 days'where p.status='published'and p.published_content is not null group by p.id order by count(c.id)desc,p.updated_at desc limit v_limit;end$$;
create or replace function public.cms_search_discovery_dashboard(p_days integer default 30)returns jsonb language plpgsql stable security definer set search_path=public as $$declare v_days integer:=least(greatest(coalesce(p_days,30),1),180);v_since timestamptz;v_summary jsonb;v_queries jsonb;v_empty jsonb;v_content jsonb;begin if not public.cms_can('read')then raise exception'permission_denied';end if;v_since:=now()-make_interval(days=>v_days);select jsonb_build_object('searches',count(*),'zero_results',count(*)filter(where result_count=0),'clicks',(select count(*)from public.cms_search_clicks where clicked_at>=v_since),'click_through_rate',case when count(*)=0 then 0 else round((select count(distinct search_event_id)from public.cms_search_clicks where clicked_at>=v_since)::numeric/count(*)::numeric,4)end)into v_summary from public.cms_search_events where searched_at>=v_since;select coalesce(jsonb_agg(to_jsonb(x)),'[]')into v_queries from(select query_text,locale,count(*)searches,round(avg(result_count),1)average_results from public.cms_search_events where searched_at>=v_since and query_text<>'[redacted sensitive query]'group by query_text,locale order by count(*)desc,query_text limit 25)x;select coalesce(jsonb_agg(to_jsonb(x)),'[]')into v_empty from(select query_text,locale,count(*)searches from public.cms_search_events where searched_at>=v_since and result_count=0 and query_text<>'[redacted sensitive query]'group by query_text,locale order by count(*)desc,query_text limit 25)x;select coalesce(jsonb_agg(to_jsonb(x)),'[]')into v_content from(select c.page_key,p.title,p.route,count(*)clicks,round(avg(c.result_position),1)average_position from public.cms_search_clicks c join public.cms_pages p on p.page_key=c.page_key where c.clicked_at>=v_since group by c.page_key,p.title,p.route order by count(*)desc limit 25)x;return jsonb_build_object('days',v_days,'summary',v_summary,'top_queries',v_queries,'zero_result_queries',v_empty,'popular_content',v_content);end$$;
revoke execute on function public.cms_search_discover(text,text,integer),public.cms_record_search_click(uuid,text,integer),public.cms_search_suggestions(text,text,integer),public.cms_popular_content(text,integer),public.cms_search_discovery_dashboard(integer)from public;
grant execute on function public.cms_search_discover(text,text,integer),public.cms_record_search_click(uuid,text,integer),public.cms_search_suggestions(text,text,integer),public.cms_popular_content(text,integer)to anon,authenticated;grant execute on function public.cms_search_discovery_dashboard(integer)to authenticated;
